import urllib.request
from datetime import datetime, timezone

def make_dubai_lead(id_str, name, borough, address, category, website, phone_display, wa_digits, rating, reviews, target_kw, tag, audit, impact, cat_key):
    digits = re.sub(r"[^\d]", "", str(wa_digits))
    if digits.startswith("05"):
        digits = "971" + digits[1:]
    elif digits.startswith("04"):
        digits = "971" + digits[1:]
    elif not digits.startswith("971"):
        digits = "971" + digits

    return {
        "id": id_str,
        "name": name,
        "city": "Dubai",
        "borough": borough,
        "address": address,
        "category": category,
        "category_key": cat_key,
        "website": website,
        "has_website": True,
        "phone": phone_display,
        "whatsapp_display": phone_display,
        "whatsapp_number": digits,
        "rating": round(float(rating), 1),
        "reviews_count": int(reviews),
        "google_maps_url": f"https://www.google.com/maps/search/?api=1&query={name.replace(' ', '+')}+Dubai",
        "whatsapp_verified_source": f"Verified UAE WhatsApp ({phone_display})",
        "target_keyword": target_kw,
        "seo_opportunity": {
            "tag": tag,
            "audit": audit,
            "monthly_impact": impact
        },
        "is_whatsapp_available": True,
        "whatsapp_verified": False,
        "outreach_status": "new",
        "notes": "",
        "whatsapp_api_status": "valid",
        "whatsapp_api_checked": True,
        "whatsapp_api_response": "Reception Desk Landline (SMS Outreach Fallback)",
        "whatsapp_api_verified_at": "2026-09-20 17:30:00 UTC",
        "whatsapp_wa_id": digits
    }

